import{_ as a,o as s,c as e,O as n}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"容量估算与压测","description":"容量估算与压测：日活怎么换算成 QPS、存储/带宽怎么估、单机能扛多少、压测怎么找拐点、扩容按什么标准算。","frontmatter":{"description":"容量估算与压测：日活怎么换算成 QPS、存储/带宽怎么估、单机能扛多少、压测怎么找拐点、扩容按什么标准算。","tags":["系统设计","MySQL","架构设计","缓存"]},"headers":[],"relativePath":"backend/系统设计/容量估算与压测.md","filePath":"backend/系统设计/容量估算与压测.md","lastUpdated":1793245104000}'),r={name:"backend/系统设计/容量估算与压测.md"};function l(d,t,o,p,i,c){return s(),e("div",null,t[0]||(t[0]=[n(`<h1 id="容量估算与压测" tabindex="-1">容量估算与压测 <a class="header-anchor" href="#容量估算与压测" aria-label="Permalink to &quot;容量估算与压测&quot;">​</a></h1><blockquote><p>「这个系统能扛多少？」是系统设计面试的必问题，也是上线前的必答题。 估算不需要精确，需要<strong>量级正确</strong>。这篇给一套能当场算的公式和一张能背下来的参考表。</p></blockquote><h2 id="一、四个基本量" tabindex="-1">一、四个基本量 <a class="header-anchor" href="#一、四个基本量" aria-label="Permalink to &quot;一、四个基本量&quot;">​</a></h2><p>任何容量问题最终都落到这四个数上：</p><table><thead><tr><th>量</th><th>单位</th><th>决定什么</th></tr></thead><tbody><tr><td><strong>QPS</strong></td><td>次/秒</td><td>需要多少台应用服务器</td></tr><tr><td><strong>存储</strong></td><td>GB/TB</td><td>需要多少磁盘、要不要分库分表</td></tr><tr><td><strong>带宽</strong></td><td>Mbps</td><td>CDN、专线、出口带宽</td></tr><tr><td><strong>连接数</strong></td><td>个</td><td>文件句柄、线程/协程数、LB 规格</td></tr></tbody></table><h2 id="二、qps-怎么估" tabindex="-1">二、QPS 怎么估 <a class="header-anchor" href="#二、qps-怎么估" aria-label="Permalink to &quot;二、QPS 怎么估&quot;">​</a></h2><h3 id="从日活推峰值" tabindex="-1">从日活推峰值 <a class="header-anchor" href="#从日活推峰值" aria-label="Permalink to &quot;从日活推峰值&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">日均 QPS = 日请求量 / 86400</span></span>
<span class="line"><span style="color:#e1e4e8;">峰值 QPS = 日均 QPS × 峰值系数</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">日均 QPS = 日请求量 / 86400</span></span>
<span class="line"><span style="color:#24292e;">峰值 QPS = 日均 QPS × 峰值系数</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>峰值系数</strong>取 2～5（业务集中型取高，如打卡、抢购；全天均匀取低）。 再乘一个<strong>安全系数</strong> 1.5～2（应对突发和后续增长）。</p><p><strong>例</strong>：日活 100 万，人均 50 次请求。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">日请求 = 100万 × 50 = 5000 万</span></span>
<span class="line"><span style="color:#e1e4e8;">日均 QPS = 5000万 / 86400 ≈ 580</span></span>
<span class="line"><span style="color:#e1e4e8;">峰值 QPS = 580 × 4 ≈ 2300</span></span>
<span class="line"><span style="color:#e1e4e8;">规划容量 = 2300 × 1.5 ≈ 3500 QPS</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">日请求 = 100万 × 50 = 5000 万</span></span>
<span class="line"><span style="color:#24292e;">日均 QPS = 5000万 / 86400 ≈ 580</span></span>
<span class="line"><span style="color:#24292e;">峰值 QPS = 580 × 4 ≈ 2300</span></span>
<span class="line"><span style="color:#24292e;">规划容量 = 2300 × 1.5 ≈ 3500 QPS</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>面试时把这三步念出来，比直接给一个数可信得多。</p><h3 id="单机能力参考-量级-别当绝对值" tabindex="-1">单机能力参考（量级，别当绝对值） <a class="header-anchor" href="#单机能力参考-量级-别当绝对值" aria-label="Permalink to &quot;单机能力参考（量级，别当绝对值）&quot;">​</a></h3><table><thead><tr><th>场景</th><th>单机 QPS（4C8G）</th></tr></thead><tbody><tr><td>纯内存计算 / 静态接口</td><td>1 万 ~ 3 万</td></tr><tr><td>一次 Redis 读 + 少量逻辑</td><td>5 千 ~ 1 万</td></tr><tr><td>一次 MySQL 主键查询</td><td>2 千 ~ 5 千</td></tr><tr><td>一次 MySQL 复杂查询 / 多表</td><td>200 ~ 800</td></tr><tr><td>一次跨服务 RPC 调用</td><td>1 千 ~ 3 千</td></tr><tr><td>一次大模型调用</td><td>1 ~ 20（受模型侧限制）</td></tr></tbody></table><blockquote><p>反直觉但重要：<strong>瓶颈几乎总在 IO</strong>。CPU 打满前，数据库或下游服务已经先跪了。</p></blockquote><h2 id="三、存储怎么估" tabindex="-1">三、存储怎么估 <a class="header-anchor" href="#三、存储怎么估" aria-label="Permalink to &quot;三、存储怎么估&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">单行大小 ≈ 各字段字节数之和（varchar 按实际长度估，不算声明长度）</span></span>
<span class="line"><span style="color:#e1e4e8;">表大小   ≈ 单行大小 × 行数 × (1 + 索引开销 20%~50%)</span></span>
<span class="line"><span style="color:#e1e4e8;">实际占用 ≈ 表大小 × 副本数 × (1 + 冗余 30%)</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">单行大小 ≈ 各字段字节数之和（varchar 按实际长度估，不算声明长度）</span></span>
<span class="line"><span style="color:#24292e;">表大小   ≈ 单行大小 × 行数 × (1 + 索引开销 20%~50%)</span></span>
<span class="line"><span style="color:#24292e;">实际占用 ≈ 表大小 × 副本数 × (1 + 冗余 30%)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>例</strong>：订单表，单行 500B，每天 100 万单，保留 3 年。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">行数 = 100万 × 365 × 3 ≈ 11 亿</span></span>
<span class="line"><span style="color:#e1e4e8;">原始 = 11亿 × 500B ≈ 550 GB</span></span>
<span class="line"><span style="color:#e1e4e8;">算索引和冗余 ×1.5 ≈ 825 GB</span></span>
<span class="line"><span style="color:#e1e4e8;">单副本 825GB，主从两份 ≈ 1.7 TB</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">行数 = 100万 × 365 × 3 ≈ 11 亿</span></span>
<span class="line"><span style="color:#24292e;">原始 = 11亿 × 500B ≈ 550 GB</span></span>
<span class="line"><span style="color:#24292e;">算索引和冗余 ×1.5 ≈ 825 GB</span></span>
<span class="line"><span style="color:#24292e;">单副本 825GB，主从两份 ≈ 1.7 TB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>结论</strong>：单表 11 亿行必须分库分表（单表建议 1000 万～2000 万行，或单表 10GB 以内）。</p><h3 id="冷热分离怎么算" tabindex="-1">冷热分离怎么算 <a class="header-anchor" href="#冷热分离怎么算" aria-label="Permalink to &quot;冷热分离怎么算&quot;">​</a></h3><p>一般 90% 的访问集中在最近 10% 的数据上：</p><ul><li><strong>热数据</strong>（近 3 个月）：放 SSD / 高配库</li><li><strong>冷数据</strong>（3 个月以前）：放归档库或对象存储，按需回查</li></ul><h2 id="四、带宽怎么估" tabindex="-1">四、带宽怎么估 <a class="header-anchor" href="#四、带宽怎么估" aria-label="Permalink to &quot;四、带宽怎么估&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">带宽(Mbps) = QPS × 单次响应大小(Byte) × 8 / 1e6</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">带宽(Mbps) = QPS × 单次响应大小(Byte) × 8 / 1e6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>例</strong>：2000 QPS，平均响应 20KB。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">2000 × 20KB × 8 / 1e6 ≈ 320 Mbps</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">2000 × 20KB × 8 / 1e6 ≈ 320 Mbps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果响应是图片/视频，先上 CDN，别让源站扛。</p><h2 id="五、压测怎么做" tabindex="-1">五、压测怎么做 <a class="header-anchor" href="#五、压测怎么做" aria-label="Permalink to &quot;五、压测怎么做&quot;">​</a></h2><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><table><thead><tr><th>工具</th><th>适合</th></tr></thead><tbody><tr><td><strong>wrk / hey</strong></td><td>压单个 HTTP 接口，轻量</td></tr><tr><td><strong>JMeter</strong></td><td>复杂场景（登录、参数关联、断言）</td></tr><tr><td><strong>k6</strong></td><td>脚本化、可进 CI</td></tr><tr><td><strong>ab</strong></td><td>最简单，别用于生产前评估（单线程模型不准）</td></tr></tbody></table><h3 id="四个必须看的指标" tabindex="-1">四个必须看的指标 <a class="header-anchor" href="#四个必须看的指标" aria-label="Permalink to &quot;四个必须看的指标&quot;">​</a></h3><table><thead><tr><th>指标</th><th>含义</th><th>关注点</th></tr></thead><tbody><tr><td><strong>QPS / TPS</strong></td><td>吞吐</td><td>拐点在哪</td></tr><tr><td><strong>P99 延迟</strong></td><td>长尾</td><td>平均延迟没意义</td></tr><tr><td><strong>错误率</strong></td><td>超时/5xx</td><td>拐点前会先抬头</td></tr><tr><td><strong>资源水位</strong></td><td>CPU/内存/连接数</td><td>谁先满谁就是瓶颈</td></tr></tbody></table><h3 id="找拐点-阶梯加压" tabindex="-1">找拐点：阶梯加压 <a class="header-anchor" href="#找拐点-阶梯加压" aria-label="Permalink to &quot;找拐点：阶梯加压&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">并发 10  → 50  → 100 → 200 → 400 → 800</span></span>
<span class="line"><span style="color:#e1e4e8;">每档跑 3~5 分钟，记录 QPS / P99 / 错误率 / CPU</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">并发 10  → 50  → 100 → 200 → 400 → 800</span></span>
<span class="line"><span style="color:#24292e;">每档跑 3~5 分钟，记录 QPS / P99 / 错误率 / CPU</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>画出来会看到：QPS 先线性上升，到某点开始<strong>变平</strong>而 P99 <strong>陡增</strong> —— 那个点就是容量拐点，规划时取它的 <strong>70%</strong>。</p><h3 id="压测的五个坑" tabindex="-1">压测的五个坑 <a class="header-anchor" href="#压测的五个坑" aria-label="Permalink to &quot;压测的五个坑&quot;">​</a></h3><ol><li><strong>数据量不对</strong>：空表压出来的 QPS 是假的，先灌到生产量级（至少百万级）。</li><li><strong>没预热</strong>：JVM 没 JIT、连接池没建满，前 30 秒数据要丢掉。</li><li><strong>压测机是瓶颈</strong>：压测机 CPU 打满或网络打满，测出来的是压测机的能力。</li><li><strong>只压单接口</strong>：真实流量是混合的，要按比例配比。</li><li><strong>没看下游</strong>：应用没事，数据库连接池先爆了。</li></ol><h2 id="六、容量规划表-面试可直接画" tabindex="-1">六、容量规划表（面试可直接画） <a class="header-anchor" href="#六、容量规划表-面试可直接画" aria-label="Permalink to &quot;六、容量规划表（面试可直接画）&quot;">​</a></h2><table><thead><tr><th>项</th><th>估算值</th><th>结论</th></tr></thead><tbody><tr><td>峰值 QPS</td><td>3500</td><td>应用 4 台（单机 1000，留 30% 余量）</td></tr><tr><td>存储 3 年</td><td>1.7 TB</td><td>分 8 库 16 表，或按用户 ID 分片</td></tr><tr><td>带宽</td><td>320 Mbps</td><td>上 CDN + 压缩</td></tr><tr><td>连接数</td><td>峰值 8 万</td><td>LB / 网关按 10 万连接规划</td></tr><tr><td>缓存</td><td>热点 20%</td><td>Redis 16GB × 主从</td></tr></tbody></table><h2 id="七、速查" tabindex="-1">七、速查 <a class="header-anchor" href="#七、速查" aria-label="Permalink to &quot;七、速查&quot;">​</a></h2><table><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>日活怎么换 QPS</td><td>日请求/86400 × 峰值系数(2~5) × 安全系数(1.5~2)</td></tr><tr><td>单机 MySQL 能扛多少</td><td>主键查询 2k~5k QPS，复杂查询几百</td></tr><tr><td>单表多大要分表</td><td>1000 万~2000 万行，或 10GB</td></tr><tr><td>带宽怎么算</td><td>QPS × 响应大小 × 8</td></tr><tr><td>压测看什么</td><td>QPS 拐点 + P99 + 错误率 + 资源水位</td></tr><tr><td>容量留多少余量</td><td>拐点的 70% 作为规划值</td></tr><tr><td>压测最常见的假数据</td><td>空表、没预热、压测机瓶颈</td></tr></tbody></table>`,42)]))}const u=a(r,[["render",l]]);export{b as __pageData,u as default};
